package ama.storage;
import ama.transcript.*;import ama.model.*;import ama.task.*;import java.util.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
/** Source-first application composition restarts from persisted configuration; no parent capability is transferred. */
class Task09GenerationApplicationRestartIT extends Task09GenerationRestartIT {
 @Override void replayAfterRestart(Map<String,Object> candidate,MinutesExternalPreparation unused,ControlledMinutesClient oldClient,JdbcExternalOperations oldOperations)throws Exception {
  app.close();oldClient.close();String id=UUID.randomUUID().toString();Path config=ROOT.resolve("application-restart-"+id+".properties"),log=ROOT.resolve("application-restart-"+id+".log");var permission=java.nio.file.attribute.PosixFilePermissions.asFileAttribute(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));Files.createFile(config,permission);Files.createFile(log,permission);
  var properties=new Properties();properties.setProperty("archive",archive.toString());properties.setProperty("pin",pin);properties.setProperty("promptVersion",prompt.version());properties.setProperty("promptSha",prompt.sha256());properties.setProperty("modelVersion",model.version());properties.setProperty("modelSha",model.sha256());properties.setProperty("nativeConfig",nativeFixture.configuration.toString());properties.setProperty("task",(String)candidate.get("task_id"));properties.setProperty("candidate",(String)candidate.get("id"));properties.setProperty("providerPort",Integer.toString(providerPort));properties.setProperty("authorization","task09-owned-provider-test-authorization-value");properties.setProperty("receipt",receipt.resolve("application-fresh-process-replay.json").toString());try(var out=Files.newOutputStream(config)){properties.store(out,"Task09 new owned restart configuration");}
  var command=List.of(Path.of(System.getProperty("java.home"),"bin/java").toString(),"-Xmx64m","-XX:ActiveProcessorCount=2","-cp",System.getProperty("surefire.test.class.path",System.getProperty("java.class.path")),"ama.storage.Task09ApplicationReplayProcess",config.toString());Files.writeString(receipt.resolve("application-restart-command.json"),json.writeValueAsString(command));Process process=new ProcessBuilder(command).redirectErrorStream(true).redirectOutput(log.toFile()).start();try{assertTrue(process.waitFor(40,java.util.concurrent.TimeUnit.SECONDS),"Application replay child deadline");assertEquals(0,process.exitValue(),"Fresh application replay failed; see child log");assertTrue(Files.exists(receipt.resolve("application-fresh-process-replay.json")));}finally{if(process.isAlive()){process.destroyForcibly();assertTrue(process.waitFor(5,java.util.concurrent.TimeUnit.SECONDS));}Files.copy(log,receipt.resolve("application-restart-child.log"));Files.writeString(receipt.resolve("application-restart-closed.json"),json.writeValueAsString(Map.of("pid",process.pid(),"parentPid",ProcessHandle.current().pid(),"alive",process.isAlive(),"exit",process.exitValue(),"parentApplicationClosed",!app.isActive())));}
 }
}
